import heapq

def match(orders):
    trades = []
    orders_map = {}  # id -> dict(side, price, qty, seq, cancelled)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)

    for seq, order in enumerate(orders):
        op = order[0]

        if op == 'cancel':
            oid = order[1]
            if oid in orders_map:
                orders_map[oid]['cancelled'] = True
            continue

        if op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            # remove invalid entries from top
            while opp_heap and (
                orders_map[opp_heap[0][2]]['qty'] <= 0 or
                orders_map[opp_heap[0][2]]['cancelled']
            ):
                heapq.heappop(opp_heap)

            if not opp_heap:
                break

            top = opp_heap[0]
            if side == 'buy':
                top_price = top[0]  # sell_heap stores actual price
            else:
                top_price = -top[0]  # buy_heap stores -price

            if op != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            heapq.heappop(opp_heap)
            oid_resting = top[2]
            resting = orders_map[oid_resting]

            trade_qty = min(remaining, resting['qty'])
            resting['qty'] -= trade_qty
            remaining -= trade_qty

            if side == 'buy':
                trades.append([oid, oid_resting, resting['price'], trade_qty])
            else:
                trades.append([oid_resting, oid, resting['price'], trade_qty])

            if resting['qty'] > 0:
                if resting['side'] == 'buy':
                    heapq.heappush(buy_heap, (-resting['price'], resting['seq'], oid_resting))
                else:
                    heapq.heappush(sell_heap, (resting['price'], resting['seq'], oid_resting))

        if op == 'limit' and remaining > 0:
            orders_map[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'seq': seq,
                'cancelled': False
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        # ioc/market remainder discarded; fully filled limit doesn't rest

    return trades

